const body = $('Native Leads Qualifier Webhook').item.json.body;
const row = $json;
if (!row || !row.id) {
  return [{ json: { respond: 'not_found' } }];
}
const fields = Array.isArray(body.fields) && body.fields.length ? body.fields : ['email','phone'];
const needEmail = fields.includes('email') && !row.email;
const needPhone = fields.includes('phone') && !row.phone;
const PRICE_EMAIL = 0.20;
const PRICE_PHONE = 2.00;
const cost = (needEmail ? PRICE_EMAIL : 0) + (needPhone ? PRICE_PHONE : 0);
const balance = Number(row.balance_usd || 0);
if (cost > 0 && balance < cost) {
  return [{ json: { respond: 'insufficient_balance', balance, required: cost } }];
}
return [{ json: {
  respond: 'proceed', needEmail: needEmail ? 'yes' : 'no', needPhone: needPhone ? 'yes' : 'no', balance,
  lead_id: row.id, tenant_id: row.tenant_id, name: row.name,
  company: row.company || '', website: row.website || '', email: row.email || '', phone: row.phone || ''
} }];

const plan = $('Plan Enrichment').item.json;
const resp = $json;
const found = resp && resp.data && resp.data.email ? resp.data.email : null;
return [{ json: { ...plan, foundEmail: found } }];

const plan = $('Plan Enrichment').item.json;
let email = plan.email;
let balance = plan.balance;
// Parse Hunter Result / PG Consume+Save Email only ran when needEmail was true AND
// (for the save step) a match was found -- $('NodeName') throws if that node never
// executed for this item, so every lookup here is guarded.
try {
  const parsed = $('Parse Hunter Result').all();
  if (parsed.length && parsed[0].json.foundEmail) {
    email = parsed[0].json.foundEmail;
    try {
      const saved = $('PG Consume+Save Email').all();
      if (saved.length && saved[0].json.new_balance != null) balance = Number(saved[0].json.new_balance);
    } catch (e) { /* save step didn't run */ }
  }
} catch (e) { /* Hunter branch didn't run -- needEmail was false */ }
return [{ json: { ...plan, email, balance } }];

const plan = $('Merge After Email').item.json;
const resp = $json;
let foundPhone = null;
if (plan.needPhone === 'yes') {
  const phones = resp && resp.data && Array.isArray(resp.data.phoneNumbers) ? resp.data.phoneNumbers : [];
  const mobile = phones.find(p => p && p.number);
  foundPhone = mobile ? mobile.number : null;
}
return [{ json: { ...plan, foundPhone } }];

const plan = $('Parse Lusha Result').item.json;
let phone = plan.phone;
let balance = plan.balance;
if (plan.foundPhone) {
  phone = plan.foundPhone;
  try {
    const saved = $('PG Consume+Save Phone').all();
    if (saved.length && saved[0].json.new_balance != null) balance = Number(saved[0].json.new_balance);
  } catch (e) { /* save step didn't run */ }
}
return [{ json: {
  success: true,
  data: { lead_id: plan.lead_id, email: plan.email || '', phone: phone || '' },
  wallet_balance: balance
} }];

